fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let l = s.len();
    let p = l - (l % 3); // largest multiple of 3 <= l

    let mut res = Vec::with_capacity(l);

    // Transform full triplets [0, p)
    for i in 0..p {
        let v = match i % 3 {
            0 => s[i + 2], // (0,1,2) -> take from 2
            1 => s[i - 1], // (0,1,2) -> take from 0
            _ => s[i - 1], // i % 3 == 2 -> take from 1
        };
        res.push(v);
    }

    // Copy unchanged suffix [p, l)
    res.extend_from_slice(&s[p..]);

    res
}